    markSheet: JSON.stringify({"domain1": {"name": "Data gathering and diagnosis", "competencies": [{"id": "1a", "doneWell": "Assesses capacity formally and confirms Robert has full capacity: he understands his condition and the risks of refusing transfusion, retains the information, weighs it against his deeply held values and communicates a consistent decision.", "donePoorly": "Does not formally assess capacity, or dismisses his capacity because he is making a decision the doctor disagrees with — capacity is decision-specific and a person has the right to make an unwise decision."}, {"id": "1b", "doneWell": "Reviews the advance decision and confirms it is valid: made when capacitous, specific to the treatment being refused, signed, witnessed and applicable to the current situation.", "donePoorly": "Does not review the advance decision document or attempts to argue it is not applicable to the current situation without legal basis."}, {"id": "1c", "doneWell": "Asks about Roberts current symptoms to assess clinical urgency and to plan alternatives: fatigue, breathlessness, dizziness, postural symptoms — and confirms the bleeding has stopped reducing immediate mortality risk.", "donePoorly": "Focuses entirely on the refusal without assessing the current clinical status and what alternatives might safely support Roberts recovery."}]}, "domain2": {"name": "Clinical management", "competencies": [{"id": "2a", "doneWell": "Respects Roberts valid advance decision refusing blood products and does not attempt to override it. Explains clearly that his decision will be respected and documented in his notes.", "donePoorly": "Attempts to persuade Robert to reconsider, implies his decision is irrational, or suggests the advance decision might not be valid without legal basis — all of which violate his autonomy and the Mental Capacity Act."}, {"id": "2b", "doneWell": "Discusses evidence-based alternatives to transfusion: IV iron infusion (rapid Hb response), erythropoietin stimulating agents, optimising nutrition, haematinics (oral iron, B12, folate), and liaising with the surgical team about haemostasis.", "donePoorly": "Accepts Roberts refusal without discussing what can actively be done to support his recovery, leaving him without a positive management plan."}, {"id": "2c", "doneWell": "Documents Roberts decision clearly in the medical record, ensures the advance decision is scanned and flagged prominently, and communicates with the surgical team about the agreed management plan.", "donePoorly": "Does not ensure Roberts decision is adequately documented and flagged, risking his wishes being overridden in an emergency by a clinician who does not know him."}, {"id": "2d", "doneWell": "Discusses the threshold at which Robert would accept hospital admission for monitoring and what constitutes a deterioration requiring emergency review, establishing a safety net that respects his decision.", "donePoorly": "Discharges Robert without a safety net or clear plan for clinical deterioration, leaving both Robert and the clinical team without guidance for an emergency scenario."}]}, "domain3": {"name": "Relating to others", "competencies": [{"id": "3a", "doneWell": "Respects Roberts faith and decision with genuine respect and without condescension or subtle pressure, demonstrating that the doctor understands the difference between a decision the doctor would not make personally and a decision that violates the patients autonomous right.", "donePoorly": "Treats Roberts faith as an obstacle to good medical care rather than as a deeply held value that defines his identity and must be respected under the Mental Capacity Act."}, {"id": "3b", "doneWell": "Focuses the consultation on what can be done rather than on what cannot be done, ensuring Robert leaves feeling supported and with a clear positive management plan.", "donePoorly": "Focuses the consultation on the risks of refusal and the doctors disagreement, leaving Robert feeling pressured and unsupported."}]}}),
