const sql = `INSERT INTO sca_cases (title, category, difficulty, patientName, patientAge, patientGender, presentingComplaint, backgroundContext, aiPatientPersona, markSheet, examinationFindings, investigationResults, isActive) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;

let inserted = 0;
for (const c of cases) {
  await connection.execute(sql, [
    c.title, c.category, c.difficulty, c.patientName, c.patientAge, c.patientGender,
    c.presentingComplaint, c.backgroundContext, c.aiPatientPersona, c.markSheet,
    c.examinationFindings, c.investigationResults, c.isActive
  ]);
  inserted++;
  console.log(`Inserted case ${30 + inserted}: ${c.title}`);
}

const [rows] = await connection.execute('SELECT COUNT(*) as total FROM sca_cases');
console.log(`\nTotal cases in database: ${rows[0].total}`);

await connection.end();
console.log('Done!');
